            style: STextStyles.navBarTitle(context),
          ),
          actions: [
            Padding(
              padding: const EdgeInsets.only(top: 10, bottom: 10, right: 10),
              child: AspectRatio(
                aspectRatio: 1,
                child: AppBarIconButton(
                  semanticsLabel: "Address List Pop-up Button. Opens A Pop-up For Address List Button.",
                  key: const Key("walletNetworkSettingsAddNewNodeViewButton"),
                  size: 36,
                  shadows: const [],
                  color: Theme.of(context).extension<StackColors>()!.background,
                  icon: SvgPicture.asset(
                    Assets.svg.verticalEllipsis,
                    color: Theme.of(context)
                        .extension<StackColors>()!
                        .accentColorDark,
                    width: 20,
                    height: 20,
                  ),
                  onPressed: () {
                    showDialog<dynamic>(
                      barrierColor: Colors.transparent,
                      barrierDismissible: true,
                      context: context,
                      builder: (_) {
                        return Stack(
                          children: [
                            Positioned(
                              top: 9,
                              right: 10,
                              child: Container(
                                decoration: BoxDecoration(
                                  color: Theme.of(context)
                                      .extension<StackColors>()!
                                      .popupBG,
                                  borderRadius: BorderRadius.circular(
                                    Constants.size.circularBorderRadius,
                                  ),
                                  // boxShadow: [CFColors.standardBoxShadow],
                                  boxShadow: const [],
                                ),
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    GestureDetector(
                                      onTap: () {
                                        Navigator.of(context).pop();
                                        final type =
                                            _walletAddressTypes[_currentIndex];
                                        Navigator.of(context).pushNamed(
                                          WalletAddressesView.routeName,
                                          // Only the type picked here, so
                                          // shield and transparent lists
                                          // stay separate.
                                          arguments: _showMultiType
                                              ? (
                                                  walletId: walletId,
                                                  type: type,
                                                  title:
                                                      "${_addressTypeLabel(type)}es",
                                                )
                                              : walletId,
                                        );
                                      },
                                      child: RoundedWhiteContainer(
                                        boxShadow: [
                                          Theme.of(context)
                                              .extension<StackColors>()!
                                              .standardBoxShadow,
                                        ],
                                        child: Material(
                                          color: Colors.transparent,
                                          child: Padding(
                                            padding: const EdgeInsets.symmetric(
                                              horizontal: 12,
                                            ),
                                            child: Text(
                                              "Address list",
                                              style: STextStyles.field(context),
                                            ),
                                          ),
                                        ),
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ),
                          ],
                        );
                      },
                    );
                  },
                ),
              ),
            ),
          ],
        ),
        body: SafeArea(
          child: Padding(
            padding: const EdgeInsets.all(12),
            child: SingleChildScrollView(
              child: Padding(
                padding: const EdgeInsets.all(4),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    ConditionalParent(
                      condition: _showMultiType,
                      builder: (child) => Column(
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          Text(
                            "Address type",
                            style: STextStyles.w500_14(context).copyWith(
                              color: Theme.of(context)
                                  .extension<StackColors>()!
                                  .infoItemLabel,
                            ),
                          ),
                          const SizedBox(height: 10),
                          DropdownButtonHideUnderline(
                            child: DropdownButton2<int>(
                              valueListenable: ValueNotifier(_currentIndex),
                              items: [
                                for (
                                  int i = 0;
                                  i < _walletAddressTypes.length;
                                  i++
                                )
                                  DropdownItem(
                                    value: i,
                                    child: Text(
                                      _addressTypeLabel(_walletAddressTypes[i]),
                                      style: STextStyles.w500_14(context),
                                    ),
                                  ),
                              ],
                              onChanged: (value) {
                                if (value != null && value != _currentIndex) {
                                  setState(() {
                                    _currentIndex = value;
                                  });
                                }
                              },
                              isExpanded: true,
                              iconStyleData: IconStyleData(
                                icon: Padding(
